mapper.select:
SELECT category_id, name, category_order, categoryicon_url
FROM categories
WHERE category_id = #{categoryId}

mapper.insert:
INSERT INTO categories (name, category_order, categoryicon_url)
SELECT #{name}, COALESCE(MAX(category_order), 0) + 1, #{categoryiconUrl}
FROM (SELECT category_order FROM categories) AS temp

mapper.update:
UPDATE categories
SET name = #{name}, categoryicon_url = #{categoryiconUrl}
WHERE category_id = #{categoryId}

UPDATE categories
SET categoryicon_url = #{categoryiconUrl}
WHERE category_id = #{categoryId}
